"use strict";(self.webpackChunkmy_blog=self.webpackChunkmy_blog||[]).push([[71],{1003:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>i,default:()=>c,frontMatter:()=>s,metadata:()=>n,toc:()=>h});var n=a(7305),o=a(4848),r=a(8453);const s={slug:"90s-gamer-series",title:"A \u201890s Gamer\u2019s Journey into the Forgotten World of Adventure Games",authors:["kalarp"],tags:["Adventure Games","Point'n'Click","90s"]},i=void 0,l={authorsImageUrls:[void 0]},h=[{value:"Part I \u2014 Love at First Byte",id:"part-i--love-at-first-byte",level:2}];function d(e){const t={h2:"h2",p:"p",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h2,{id:"part-i--love-at-first-byte",children:"Part I \u2014 Love at First Byte"}),"\n",(0,o.jsx)(t.p,{children:"I remember my first computer \u2014 a rubber-keyed ZX Spectrum. I don\u2019t recall the exact day my dad brought it home, but I can still picture myself sitting in front of a small CRT screen, trying to make sense of a simple game. That state-of-the-art device didn\u2019t stay cutting-edge for long. It was soon replaced by an even more advanced Commodore 64 \u2014 a larger keyboard boasting what felt like an impressive four function keys and a loading screen that seemed to take forever. But once the main menu appeared, I\u2019d grab the joystick and lose myself in a 320 x 200 resolution world rendered in a 16-colour palette. All of it led me to the machine that hardwired the gamer gene straight into my DNA: a PC."}),"\n",(0,o.jsx)(t.p,{children:"I witnessed it all \u2014 each upgrade from the 286, 386, and 486 DX2 to my first Pentium processor; the evolution of games from 2D to 3D, powered by my first Voodoo graphics card; and the shift from simple synthesised music to full orchestral soundtracks, thanks to the Sound Blaster. Not to mention the transition from MS-DOS to the revolutionary Windows 3.11 \u2014 an early step toward what would become the world\u2019s most popular operating system."}),"\n",(0,o.jsx)(t.p,{children:"Every hardware upgrade marked a new milestone in my gaming experience. I went from shooting aliens in Duke Nukem 3D to racing opponents in the first Need for Speed. One day, I was building bases in Command & Conquer; the next, I was throwing punches and practising fatalities in the revolutionary Mortal Kombat. I could fill pages with the titles that shaped my childhood, but one genre truly stole my heart. Point-and-click adventure games became one of the defining genres of the \u201890s gaming era."}),"\n",(0,o.jsx)(t.p,{children:"The term \u201cpoint-and-click\u201d perfectly sums up the core mechanic of these games: hovering your mouse over a beautifully crafted pixel-art world and clicking on objects to interact with them. These interactions were what pushed the plot forward. Puzzles typically involved finding an item and figuring out where \u2014 or how \u2014 to use it, often in delightfully unexpected ways. At times, you were drawn into a cleverly written dialogue where choosing the right response could unlock a clue or open up a new path. These games were often filled with humour and references to current events and pop culture of the time. The puzzles were tough and required thinking. More than once, walkthroughs from gaming magazines were a lifeline, even though game boxes often included thick manuals packed with hints."}),"\n",(0,o.jsx)(t.p,{children:"The history of the genre dates back to the early \u201980s and is closely tied to the invention of the computer mouse. While several early titles are considered pioneers of point-and-click adventure games, Enchanted Scepters \u2014 an Apple Macintosh title \u2014 is widely regarded as the first true example. But for me, the genre owes its popularity and golden era to the games developed by Sierra On-Line."}),"\n",(0,o.jsx)(t.p,{children:"Founded as On-Line Systems by Ken and Roberta Williams in 1979, the company would go on to become one of the most renowned producers of adventure games. Their first title, Mystery House, was a horror game where players explored a mysterious mansion, uncovering the identity of a killer through text-based commands. But the true milestone \u2014 the game that marked the beginning of a new era \u2014 was King\u2019s Quest: Quest for the Crown, their first true classic. In it, you play as Sir Graham, tasked with recovering three ancient artefacts: a magic mirror, a chest of gold, and an enchanted shield. Along the way, he visits a range of locations and encounters both bandits and beasts. The character is controlled using directional keys alongside typed commands like \u201cpick up\u201d or \u201cuse\u201d to solve puzzles. The original series went on to span seven sequels, of which King\u2019s Quest V remains my personal favourite. Sierra went on to produce some of the most iconic adventure game series of the era, including Leisure Suit Larry, Police Quest, Quest for Glory, and Space Quest."}),"\n",(0,o.jsx)(t.p,{children:"Another studio that helped shape the adventure game universe emerged from the world of film and television: Lucasfilm Ltd., founded by visionary filmmaker George Lucas. It\u2019s no surprise that LucasArts, the company\u2019s game division, released numerous titles set in the Star Wars universe. After all, the brand is deeply associated with that iconic saga.\r\nBut beyond the Force, LucasArts also became a legendary name in the world of point-and-click adventure games, producing titles that are now considered cult classics."}),"\n",(0,o.jsx)(t.p,{children:"If you ask me about LucasArts, The Secret of Monkey Island is the first title that springs to mind. In the game, you play as a young man named Guybrush Threepwood, whose greatest dream is to become a pirate. Unfortunately, his knack for getting into trouble tends to complicate things."}),"\n",(0,o.jsx)(t.p,{children:"A close second for me is Indiana Jones and the Fate of Atlantis. I\u2018ve always been a fan of the Indiana Jones films. As a kid, I used to watch Raiders of the Lost Ark on a VHS tape every single day after school. I still remember seeing Indiana Jones and the Last Crusade in the cinema, with River Phoenix playing young Indy. So when I got to help my childhood hero search for the legendary city of Atlantis, it was a dream come true. The game was filled with humour and perfectly captured the spirit of Spielberg\u2019s blockbusters. It remains the most successful point-and-click adventure game LucasArts ever made."}),"\n",(0,o.jsx)(t.p,{children:"The titles mentioned so far are by no means a complete list of the adventure games that left a lasting mark on the history of computer gaming. On the contrary, they\u2019re just a handful of highlights from a genre with a rich and extensive legacy. In the following parts, we\u2019ll take a closer look at some of these iconic titles. Point-and-click games refuse to be forgotten. The nostalgia for pixel graphics continues to influence the modern era, whether through minimalist pixel art or indie games crafted by passionate developers. These games from the late \u201880s and early \u201890s have etched themselves into the memories of a generation of young gamers, and their legacy still inspires today."})]})}function c(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},7305:e=>{e.exports=JSON.parse('{"permalink":"/my-blog/90s-gamer-series","source":"@site/blog/2025-05-12-90s-gamer-series.md","title":"A \u201890s Gamer\u2019s Journey into the Forgotten World of Adventure Games","description":"Part I \u2014 Love at First Byte","date":"2025-05-12T00:00:00.000Z","tags":[{"inline":true,"label":"Adventure Games","permalink":"/my-blog/tags/adventure-games"},{"inline":true,"label":"Point\'n\'Click","permalink":"/my-blog/tags/pointn-click"},{"inline":true,"label":"90s","permalink":"/my-blog/tags/90-s"}],"readingTime":5.2,"hasTruncateMarker":false,"authors":[{"name":"Piotr Kalarus","title":"Technical Writer, Translator","url":"https://www.linkedin.com/in/kalarp/","page":{"permalink":"/my-blog/authors/kalarp"},"socials":{"linkedin":"https://www.linkedin.com/in/kalarp/","github":"https://github.com/kalarp"},"imageURL":"https://kalarp.github.io/images/photo.jpg","key":"kalarp"}],"frontMatter":{"slug":"90s-gamer-series","title":"A \u201890s Gamer\u2019s Journey into the Forgotten World of Adventure Games","authors":["kalarp"],"tags":["Adventure Games","Point\'n\'Click","90s"]},"unlisted":false,"nextItem":{"title":"How to Deal With an Unresponsive SME","permalink":"/my-blog/unresponsive-sme"}}')},8453:(e,t,a)=>{a.d(t,{R:()=>s,x:()=>i});var n=a(6540);const o={},r=n.createContext(o);function s(e){const t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);